12	/**
13	 * FR-011 / R8: later steps open only when step 1 was completed AND its saved values are still
14	 * valid against the current CMS fields. Otherwise the completion is cleared and the person goes
15	 * back to step 1, where the errors show. Fields that fail to load also go back to step 1.
16	 */
17	export const step1CompleteGuard: CanActivateFn = async (
18	  route: ActivatedRouteSnapshot,
19	): Promise<boolean | UrlTree> => {
20	  const session = inject(QuoteSessionStore);
21	  const router = inject(Router);
22	  const country = route.parent?.paramMap.get('country') ?? route.paramMap.get('country') ?? '';
23	  const toStep1 = router.createUrlTree(['/', country, 'quote']);
24	  if (!session.isStep1Completed()) return toStep1;
25	
26	  const active = inject(WizardCountry).country();
27	  try {
28	    const sections = await firstValueFrom(inject(FormFieldService).load(country));
29	    const stored = session.readStep1();
30	    const ctx = { legalAge: active?.legalAge ?? 18, today: new Date() };
31	    const controls: Record<string, FormControl<FieldValue>> = {};
32	    for (const field of [...sections.policyholder, ...sections.vehicle]) {
33	      controls[field.key] = new FormControl<FieldValue>(restoredValue(field, stored[field.key]), {
34	        nonNullable: true,
35	        validators: buildValidators(field.rules, ctx, field.key),
36	      });
37	    }
38	    if (new FormGroup(controls).valid) return true;
39	  } catch {
40	    /* fields failed to load: step 1 shows its own error and retry */
41	  }
42	  session.clearStep1Completed();
43	  return toStep1;
44	};
