25	export { restoredValue };
26	
27	type Step1Group = FormGroup<Record<string, FormControl<FieldValue>>>;
28	
29	interface SectionView {
30	  id: 'policyholder' | 'vehicle';
31	  title: string;
32	  fields: { field: FormFieldDescriptor; delay: number }[];
33	  titleDelay: number;
34	}
35	
36	const SECTION_TITLES: Record<SectionView['id'], string> = {
37	  policyholder: 'Tus datos',
38	  vehicle: 'Tu vehículo',
39	};
40	
41	@Component({
42	  selector: 'app-step1-form-page',
43	  imports: [ReactiveFormsModule, StepperComponent, FormFieldComponent],
44	  changeDetection: ChangeDetectionStrategy.OnPush,
45	  templateUrl: './step1-form.page.html',
