48	export class Step1FormPage {
49	  private readonly wizardCountry = inject(WizardCountry);
50	  private readonly fieldService = inject(FormFieldService);
51	  private readonly session = inject(QuoteSessionStore);
52	  private readonly router = inject(Router);
53	  private readonly route = inject(ActivatedRoute);
54	  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
55	  private readonly destroyRef = inject(DestroyRef);
56	
57	  protected readonly steps = ['Tus datos', 'Elige tu plan', 'Resumen'];
58	  protected readonly loading = signal(true);
59	  protected readonly failed = signal(false);
60	  protected readonly submitted = signal(false);
61	  protected readonly statusMessage = signal('');
62	  protected readonly form = signal<Step1Group | null>(null);
63	  private readonly loaded = signal<FormSections | null>(null);
64	  private loadSub: Subscription | null = null;
65	
66	  protected readonly sections = computed<SectionView[]>(() => {
67	    const data = this.loaded();
68	    if (!data) return [];
69	    let index = 1; // 0 is the card header
70	    const views: SectionView[] = [];
71	    for (const id of ['policyholder', 'vehicle'] as const) {
72	      const fields = data[id];
73	      if (fields.length === 0) continue;
74	      const titleDelay = index++;
75	      views.push({
76	        id,
77	        title: SECTION_TITLES[id],
78	        titleDelay,
79	        fields: fields.map((field) => ({ field, delay: index++ })),
80	      });
81	    }
82	    return views;
83	  });
84	  protected readonly isEmpty = computed(
85	    () => !this.loading() && !this.failed() && this.sections().length === 0,
86	  );
87	  protected readonly buttonDelay = computed(
88	    () => 1 + this.sections().reduce((n, s) => n + 1 + s.fields.length, 0),
89	  );
90	
91	  constructor() {
92	    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
93	    this.load();
94	  }
95	
96	  protected load(): void {
97	    const country = this.wizardCountry.country();
98	    if (!country) return;
99	    this.loadSub?.unsubscribe();
100	    this.loading.set(true);
101	    this.failed.set(false);
102	    this.loadSub = this.fieldService.load(country.code).subscribe({
103	      next: (sections) => {
104	        this.form.set(this.buildForm(sections, country.legalAge));
105	        this.loaded.set(sections);
106	        this.loading.set(false);
107	      },
108	      error: () => {
109	        this.failed.set(true);
110	        this.loading.set(false);
111	      },
112	    });
113	  }
114	
115	  private buildForm(sections: FormSections, legalAge: number): Step1Group {
116	    const stored = this.session.readStep1();
117	    const today = new Date();
118	    const controls: Record<string, FormControl<FieldValue>> = {};
119	    for (const field of [...sections.policyholder, ...sections.vehicle]) {
120	      const initial = restoredValue(field, stored[field.key]);
121	      controls[field.key] = new FormControl<FieldValue>(initial, {
122	        nonNullable: true,
123	        validators: buildValidators(field.rules, { legalAge, today }, field.key),
124	      });
125	    }
126	    const group: Step1Group = new FormGroup(controls);
127	    group.valueChanges
128	      .pipe(takeUntilDestroyed(this.destroyRef))
129	      .subscribe(() => this.session.saveStep1(group.getRawValue()));
130	    return group;
131	  }
132	
133	  protected control(key: string): FormControl<FieldValue> {
134	    return this.form()!.controls[key];
135	  }
136	
137	  protected submit(): void {
138	    const form = this.form();
139	    if (!form) return;
140	    this.submitted.set(true);
141	    form.markAllAsTouched();
142	    if (form.invalid) {
143	      const count = Object.values(form.controls).filter((c) => c.invalid).length;
144	      // Same text twice in a row is not re-announced: clear first, then set on the next tick.
145	      this.statusMessage.set('');
146	      queueMicrotask(() =>
147	        this.statusMessage.set(
148	          count === 1 ? 'Revisa el campo marcado.' : `Revisa los ${count} campos marcados.`,
149	        ),
150	      );
151	      this.focusFirstInvalid(form);
152	      return;
153	    }
154	    this.session.markStep1Completed();
155	    void this.router.navigate(['plans'], { relativeTo: this.route });
156	  }
157	
158	  private focusFirstInvalid(form: Step1Group): void {
159	    for (const section of this.sections()) {
160	      for (const { field } of section.fields) {
161	        if (form.controls[field.key].invalid) {
162	          this.host.nativeElement.querySelector<HTMLElement>(`#${fieldInputId(field.key)}`)?.focus();
163	          return;
164	        }
165	      }
166	    }
167	  }
168	}
