18	import { QuoteSessionStore } from '../../core/session/quote-session.store';
19	import { StepperComponent } from '../../shared/ui/stepper/stepper.component';
20	import { WizardCountry } from '../quote-wizard/wizard-country.service';
21	import { PlanCardComponent } from './components/plan-card/plan-card.component';
22	import { Plan, PlanOffer } from './data/plan.model';
23	import { PlanService } from './data/plan.service';
24	import { Ages, agesFromStep1 } from './pricing/ages-from-step1';
25	import { formatPrice } from './pricing/format-price';
26	import { simulatePrice } from './pricing/simulate-price';
