31	@Component({
32	  selector: 'app-plan-list-page',
33	  imports: [StepperComponent, PlanCardComponent],
34	  changeDetection: ChangeDetectionStrategy.OnPush,
35	  // None: Swiper builds some elements (dots) itself, so its classes must be styled globally.
36	  encapsulation: ViewEncapsulation.None,
37	  templateUrl: './plan-list.page.html',
38	  styleUrl: './plan-list.page.scss',
39	})
40	export class PlanListPage {
41	  private readonly wizardCountry = inject(WizardCountry);
42	  private readonly planService = inject(PlanService);
43	  private readonly session = inject(QuoteSessionStore);
44	  private readonly router = inject(Router);
45	  private readonly route = inject(ActivatedRoute);
46	  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
47	  private readonly destroyRef = inject(DestroyRef);
48	
49	  protected readonly steps = ['Tus datos', 'Elige tu plan', 'Resumen'];
50	  protected readonly loading = signal(true);
51	  protected readonly failed = signal(false);
52	  protected readonly slider = signal(false);
53	  protected readonly selectedId = signal<string | null>(null);
54	  private readonly plans = signal<Plan[]>([]);
55	  private readonly ages = signal<Ages>({ driverAge: null, vehicleAge: null });
56	  private loadSub: Subscription | null = null;
57	  private swiper: Swiper | null = null;
58	
59	  protected readonly offers = computed<PlanOffer[]>(() => {
60	    const country = this.wizardCountry.country();
61	    if (!country) return [];
62	    const { driverAge, vehicleAge } = this.ages();
63	    return this.plans().map((plan) => {
64	      const finalPrice = simulatePrice(plan.basePrice, driverAge, vehicleAge, country);
65	      return { plan, finalPrice, formattedPrice: formatPrice(finalPrice, country) };
66	    });
67	  });
68	  protected readonly isEmpty = computed(
69	    () => !this.loading() && !this.failed() && this.offers().length === 0,
70	  );
71	  protected readonly actionsDelay = computed(() => this.offers().length + 1);
72	
73	  constructor() {
74	    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
75	    this.watchViewport();
76	    afterRenderEffect(() => {
77	      if (this.slider() && this.offers().length > 0) this.mountSwiper();
78	      else this.unmountSwiper();
79	    });
80	    this.destroyRef.onDestroy(() => {
81	      this.loadSub?.unsubscribe();
82	      this.unmountSwiper();
83	    });
84	    this.load();
85	  }
86	
87	  protected load(): void {
88	    const country = this.wizardCountry.country();
89	    if (!country) return;
90	    this.loadSub?.unsubscribe();
91	    this.loading.set(true);
92	    this.failed.set(false);
93	    this.plans.set([]);
94	    this.loadSub = this.planService.load(country.code).subscribe({
95	      next: (plans) => {
96	        this.ages.set(agesFromStep1(this.session.readStep1(), new Date()));
97	        this.plans.set(plans);
98	        this.restoreChoice(plans);
99	        this.loading.set(false);
100	      },
101	      error: () => {
102	        this.failed.set(true);
103	        this.loading.set(false);
104	      },
105	    });
106	  }
107	
108	  /** FR-009: keeps the saved choice only while the plan is still offered. */
109	  private restoreChoice(plans: Plan[]): void {
110	    const saved = this.session.readPlanId();
111	    if (saved && plans.some((plan) => plan.id === saved)) {
112	      this.selectedId.set(saved);
113	      return;
114	    }
115	    if (saved) this.session.clearPlan();
116	    this.selectedId.set(null);
117	  }
118	
119	  protected choose(planId: string): void {
120	    this.selectedId.set(planId);
121	    this.session.savePlan(planId);
122	    const index = this.offers().findIndex((offer) => offer.plan.id === planId);
123	    if (index >= 0) this.swiper?.slideTo(index);
124	  }
125	
126	  protected backToStep1(): void {
127	    void this.router.navigate(['..'], { relativeTo: this.route });
128	  }
129	
130	  protected continue(): void {
131	    if (!this.selectedId()) return;
132	    void this.router.navigate(['..', 'summary'], { relativeTo: this.route });
133	  }
134	
135	  private watchViewport(): void {
136	    if (typeof matchMedia !== 'function') return;
137	    const query = matchMedia(SLIDER_QUERY);
138	    this.slider.set(query.matches);
139	    const onChange = (event: MediaQueryListEvent) => this.slider.set(event.matches);
140	    query.addEventListener('change', onChange);
141	    this.destroyRef.onDestroy(() => query.removeEventListener('change', onChange));
142	  }
143	
144	  private mountSwiper(): void {
145	    if (this.swiper) return;
146	    const root = this.host.nativeElement;
147	    const container = root.querySelector<HTMLElement>('.plan-list__viewport');
148	    if (!container) return;
149	    const offers = untracked(this.offers);
150	    const selectedId = untracked(this.selectedId);
151	    const chosen = offers.findIndex((offer) => offer.plan.id === selectedId);
152	    const highlighted = offers.findIndex((offer) => offer.plan.highlighted);
153	    this.swiper = new Swiper(container, {
154	      modules: [Navigation, Pagination, A11y, Keyboard],
155	      initialSlide: Math.max(0, chosen >= 0 ? chosen : highlighted),
156	      slidesPerView: 1.2,
157	      centeredSlides: true,
158	      spaceBetween: 16,
159	      loop: false,
160	      breakpoints: { 768: { slidesPerView: 2.2 } },
161	      keyboard: { enabled: true, onlyInViewport: true },
162	      navigation: {
163	        prevEl: root.querySelector<HTMLElement>('.plan-list__nav--prev'),
164	        nextEl: root.querySelector<HTMLElement>('.plan-list__nav--next'),
165	      },
166	      pagination: { el: root.querySelector<HTMLElement>('.plan-list__dots'), clickable: true },
167	      a11y: {
168	        prevSlideMessage: 'Plan anterior',
169	        nextSlideMessage: 'Plan siguiente',
170	        paginationBulletMessage: 'Ir al plan {{index}}',
171	        firstSlideMessage: 'Este es el primer plan',
172	        lastSlideMessage: 'Este es el último plan',
173	        slideLabelMessage: 'Plan {{index}} de {{slidesLength}}',
174	      },
175	    });
176	  }
177	
178	  private unmountSwiper(): void {
179	    this.swiper?.destroy(true, true);
180	    this.swiper = null;
181	  }
182	}
