3	/** Formats a whole-unit amount in the country's currency, no decimals, e.g. "$ 145.000 / mes". */
4	export function formatPrice(
5	  amount: number,
6	  country: Pick<Country, 'currency' | 'numberLocale'>,
7	): string {
8	  const formatted = new Intl.NumberFormat(country.numberLocale, {
9	    style: 'currency',
10	    currency: country.currency,
11	    minimumFractionDigits: 0,
12	    maximumFractionDigits: 0,
13	  }).format(amount);
14	  return `${formatted} / mes`;
15	}
